	values, err := s.records.SchemaVersions(ctx)
	if err != nil {
		return nil, err
	}
	var result []*enrollment.FormSchema
	for _, value := range values {
		result = append(result, enrollment.CopyFormSchema(value))
	}
	return result, nil
}

func (s *FormSchemas) SchemaVersion(ctx context.Context, id int64) (*enrollment.FormSchema, error) {
	if id <= 0 {
		return nil, fmt.Errorf("schema id must be positive")
	}
	schema, err := s.records.Schema(ctx, id)
	if err != nil {
		if s.notFound(err) {
			return nil, fmt.Errorf("%w: %w", enrollment.ErrFormSchemaNotFound, err)
		}
		return nil, err
	}
	return enrollment.CopyFormSchema(schema), nil
}

func (h *HolidayHostParticipants) HostedHolidayWeeks(ctx context.Context, host enrollment.HolidayHost) ([]enrollment.HostedHolidayWeek, error) {
	if host.SchoolID <= 0 {
		return nil, errors.New("enrollment: the hosting school is required")
	}
	weeks, err := h.store.ListHostedHolidayWeeks(ctx, host.SchoolID, h.today())
	if err != nil {
		return nil, err
	}
	if weeks == nil {
		weeks = []enrollment.HostedHolidayWeek{}
	}
	return weeks, nil
}

