	return foundHolidayPeriod(h.store.FindHolidayPeriod(ctx, organizationID, periodID, false))
}

func (h *HolidayPeriods) ListHolidayPeriods(ctx context.Context, organizationID int64) ([]enrollment.HolidayPeriod, error) {
	if organizationID <= 0 {
		return nil, errHolidayPeriodRequired
	}
	periods, err := h.store.ListHolidayPeriods(ctx, organizationID)
	if err != nil {
		return nil, fmt.Errorf("enrollment: list holiday periods: %w", err)
	}
	return periods, nil
}

func (s *Phases) ListPublicOpen(ctx context.Context, now time.Time) ([]*enrollment.Phase, error) {
	if now.IsZero() {
		now = time.Now()
	}
	return s.deps.Records.PublicOpenPhases(ctx, now)
}

func (s *Phases) PhaseByID(ctx context.Context, id int64) (*enrollment.Phase, error) {
	if id <= 0 {
		return nil, enrollment.ErrPhaseNotFound
	}
	phase, err := s.deps.Records.Phase(ctx, id)
	if err != nil {
		if s.notFound(err) {
			return nil, enrollment.ErrPhaseNotFound
		}
		return nil, fmt.Errorf("get phase %d: %w", id, err)
	}
	return phase, nil
}

func (m *Service) AccountRequests(ctx context.Context, accountID int64, accountEmail string) ([]enrollment.AccountRequest, error) {
	if accountID <= 0 {
		return nil, fmt.Errorf("parent: account_id must be positive")
	}
	return m.store.AccountRequests(ctx, accountID, strings.ToLower(strings.TrimSpace(accountEmail)))
}

func (m *Service) BackfillGuardianAccountID(ctx context.Context, accountID int64, email string) (int, error) {
	if accountID <= 0 {
		return 0, fmt.Errorf("parent: account_id must be positive")
	}
	email = strings.ToLower(strings.TrimSpace(email))
	if email == "" {
		return 0, nil
	}
	return m.store.BackfillGuardianAccountID(ctx, accountID, email)
}

func (m *Service) DeleteExpiredSubmissionRateLimits(ctx context.Context) (int, int, error) {
	deleted, err := m.store.CleanupExpired(ctx)
	if err != nil {
		return 0, 0, err
	}
	return deleted, submissionRateLimitRetentionDays, nil
}

